#!/usr/bin/env python3
"""Publicador reproducible de FVMarket: Stripe, checkout invitado y empaquetado."""
from __future__ import annotations

import base64
import gzip
import os
from pathlib import Path
import subprocess
import tarfile

ROOT = Path(__file__).resolve().parent
os.chdir(ROOT)
APP = ROOT / "appsrc"
FILES = {"appsrc/operations_accounting_v1.js":"","appsrc/package-lock.json":"","appsrc/package.json":"","appsrc/procurement_v2.js":"","appsrc/public/fvmarket-admin-control-v2.js":"","appsrc/public/fvmarket-operations-v1.js":"","appsrc/public/fvmarket-storefront-v2.js":"","appsrc/public/index.html":"","appsrc/server.js":"","appsrc/test/core.test.js":"","appsrc/transactional_emails.js":"","render.yaml":""}
DELETE = ("appsrc/public/fvmarket-fulfillment-v1.js",)
EXCLUDED_PARTS = {"node_modules", "test", ".git", "data"}


def run(*args: str, cwd: Path = ROOT) -> None:
    subprocess.run(args, cwd=cwd, check=True)


def apply_sources() -> None:
    for relative, payload in FILES.items():
        target = ROOT / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(gzip.decompress(base64.b64decode(payload)))
    for relative in DELETE:
        (ROOT / relative).unlink(missing_ok=True)


def package() -> None:
    app = ROOT / "appsrc"
    archive = ROOT / "fvmarket-app.tgz"
    with tarfile.open(archive, "w:gz") as bundle:
        for path in sorted(app.rglob("*")):
            if any(part in EXCLUDED_PARTS for part in path.relative_to(app).parts):
                continue
            bundle.add(path, arcname="./" + path.relative_to(app).as_posix(), recursive=False)
    (ROOT / "fvmarket-app.tgz.b64").write_bytes(base64.encodebytes(archive.read_bytes()))
    archive.unlink()


apply_sources()
run("npm", "ci", "--omit=dev", cwd=APP)
run("npm", "test", cwd=APP)
run("node", "--check", "server.js", cwd=APP)
for source in sorted((APP / "public").glob("*.js")):
    run("node", "--check", str(source.relative_to(APP)), cwd=APP)
package()
run("git", "add", "render.yaml")
print("FVMarket actualizado, validado y empaquetado correctamente.")
